UPDATE mk_benefit_outbox
SET publish_attempts = #{attempts}, dead_lettered_at = #{deadAt}, last_error = #{error}
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}
  AND published_at IS NULL AND dead_lettered_at IS NULL

UPDATE mk_benefit_outbox
SET publish_attempts = #{attempts}, next_attempt_at = #{nextAttemptAt}, last_error = #{error}
WHERE tenant_id = #{tenantId} AND event_id = #{eventId} AND published_at IS NULL
